function rebuildFloor(){buildInterior(interior);addFloorFeatures(interior);}
function elevatorDialog(){
 if(!interior||elevatorTrip||activity)return;const total=interior.floors??Math.max(1,Math.floor(interior.height/4));dialog(interior.name+' · 电梯',`当前${interiorFloor}层，共${total}层。选择楼层后，电梯门关闭并升降。`);
 for(let f=1;f<=total;f++)row(f+'层',f===1?'一楼大厅 / 出口':interior.id==='residence'?`${f}01 可买房 · ${f}02 ${housing.resident(f)}`:'楼上大厅 / 城市窗景',()=>takeElevator(f),'前往');
}
function takeElevator(f){
 if(!interior||elevatorTrip||activity||!Number.isInteger(f)||f<1||f>(interior.floors??Math.floor(interior.height/4)))return false;
 $('dialog').close();viewingHome=false;if(f===interiorFloor)return true;keys.clear();player.g.position.set(269,(interiorFloor-1)*4,6);
 const lift=new THREE.Group();inside.add(lift);box(lift,269,-.1,6,4,.2,4,0x748e9b);box(lift,269,1.8,4,4,3.6,.2,0xa5b7bc);box(lift,267,1.8,6,.2,3.6,4,0xb6c7cb);box(lift,269,1.8,8,4,3.6,.2,0xb6c7cb);sign(lift,'电梯正在运行',269,3,7.8,3.6);lift.position.y=(interiorFloor-1)*4;
 elevatorTrip={from:interiorFloor,to:f,elapsed:0,duration:2+Math.abs(f-interiorFloor)*.18,lift};sound.play('toll');return true;
}
function updateElevator(dt){if(!elevatorTrip)return;const e=elevatorTrip;e.elapsed+=dt;const t=Math.min(1,e.elapsed/e.duration),y=(e.from-1+(e.to-e.from)*(t*t*(3-2*t)))*4;player.g.position.y=y;e.lift.position.y=y;$('prompt').textContent=`电梯 ${e.from}F → ${e.to}F`;if(t===1){interiorFloor=e.to;elevatorTrip=null;rebuildFloor();sound.play('toll');toast('电梯门打开，已到'+interiorFloor+'层。');}}
function housingDialog(){if(interior?.id!=='residence')return;dialog(interior.name+' · 房源',`共${interior.floors}层。每层的02室已有NPC入住，01室可以购买。`);row('乘电梯看房','先到2层以上，走近01室门口。',elevatorDialog,'选楼层');if(interiorFloor>1)row(interiorFloor+'01 · 88㎡ · ¥680,000',housing.owns(interior,interiorFloor,world.country)?'房屋已经属于你':'带家具的两居室，可入住',()=>buyHome(),housing.owns(interior,interiorFloor,world.country)?'回家':'购买');row('邻居 '+housing.resident(Math.max(2,interiorFloor)),'NPC住在同层02室，可以在走廊聊天。');}
