function enter(b){if(flight)return;if(b.id==='hotel')hotelKey=false;if(taxi?.phase==='riding')return;if(justice.phase!=='free')return;if(driving){toast('先下车，再进入'+b.name+'。');return;}interiorFloor=1;viewingHome=false;elevatorTrip=null;interior=b;city.visible=false;inside.visible=true;buildInterior(b);addFloorFeatures(b);scene.fog=new THREE.Fog(0xd5ddc5,60,160);player.g.removeFromParent();inside.add(player.g);player.g.position.set(260,0,7);heading=Math.PI;player.g.rotation.y=heading;orbit=0;pitch=0;$('exit').hidden=false;$('location').textContent=b.name;toast('已进入'+b.name+'，走到柜台找'+b.role+'互动。');}
function leave(){if(flight)return;if(justice.phase!=='free')return;if(!interior)return;if(elevatorTrip){toast('电梯到站后再出门。');return;}if(viewingHome){viewingHome=false;rebuildFloor();toast('已经回到小区楼层走廊。');return;}if(interiorFloor>1){takeElevator(1);return;}if(activity){toast('请先完成当前活动。');return;}const b=interior;interior=null;inside.visible=false;city.visible=true;city.add(player.g);player.g.position.set(b.door.x,surfaceHeight(b.door.x,b.door.z+2),b.door.z+2);scene.fog=new THREE.Fog(0xc6e0e8,140,330);$('exit').hidden=true;orbit=0;pitch=0;toast('回到城市街道。');}
$('exit').onclick=leave;
function toggleCar(){if(flight)return;if(navigation){navigation=null;speed=0;}if(taxi){if(taxi.phase==='waiting'&&taxi.car.g.position.distanceTo(player.g.position)<7){verifyTaxi();return;}if(taxi.phase==='riding'||taxi.phase==='verify'){toast('请等待司机完成行程。');return;}}if(justice.phase!=='free')return;if(interior||activity){toast('请先回到街道。');return;}if(driving){if(Math.abs(speed)>1){toast('先停稳，再下车。');return;}const p=activeCar.g.position;let candidate=null;for(const offset of [4,-4,5]){const q={x:p.x+Math.cos(heading)*offset,z:p.z-Math.sin(heading)*offset};if(validMove(player.g.position,q,.5)){candidate=q;break;}}if(!candidate){toast('旁边没有下车空间，请换个位置停车。');return;}driving=false;signal=null;player.g.visible=true;player.g.position.set(candidate.x,surfaceHeight(candidate.x,candidate.z),candidate.z);speed=0;activeCar=null;toast('已下车。');}else{const candidates=parked.filter(c=>c.g.position.distanceTo(player.g.position)<6).sort((a,b)=>a.g.position.distanceTo(player.g.position)-b.g.position.distanceTo(player.g.position));if(!candidates.length){toast('走近停放的车，按 F 上车。');return;}activeCar=candidates[0];playerPlate=activeCar.plate;const direction=activeCar.g.getWorldDirection(new THREE.Vector3());heading=Math.atan2(direction.x,direction.z);city.attach(activeCar.g);activeCar.g.rotation.set(0,heading,0);delete activeCar.chunk;signal=null;driving=true;speed=0;player.g.visible=false;toast('已上车！W 前进，S 倒车，A/D 转向，空格刹车。');}}
$('car-toggle').onclick=toggleCar;$('recover').onclick=()=>{if(flight)return;navigation=null;if(taxi?.phase==='riding'){toast('正在乘车，请等司机送达。');return;}cancelTaxi(false);if(justice.phase!=='free')return;if(world.mode==='highway'){world.cancelHighway();if(activeCar){activeCar.g.position.set(9,0,17);activeCar.g.rotation.set(0,Math.PI,0);}}if(interior){elevatorTrip=null;interiorFloor=1;viewingHome=false;leave();}if(activity)return;driving=false;activeCar=null;speed=0;player.g.visible=true;player.g.position.set(8,0,12);heading=Math.PI;toast('已回到广场。');};
function validMove(from,to,r){if(interior){if(interior.id==='hotel'&&Math.min(from.x,to.x)<263+r&&Math.max(from.x,to.x)>263-r&&(!hotelKey||to.z<r||to.z>5-r))return false;return to.x>248+r&&to.x<272-r&&to.z>-10+r&&to.z<10-r;}if(world.blocked(from,to,r))return false;if(Math.abs(surfaceHeight(to.x,to.z)-surfaceHeight(from.x,from.z))>.8)return false;if(world.mode==='city'){if(!canEnterGarage(from,to))return false;if(garageAccess.blocks(from,to,r,driving?activeCar.plate:playerPlate))return false;if(terrainHeight(from.x,from.z)<-1&&Math.abs(terrainHeight(to.x,to.z)-terrainHeight(from.x,from.z))>.7)return false;}const y=surfaceHeight(to.x,to.z);return !solids.some(b=>y>=(b.minY??0)-2&&y<(b.maxY??1000)&&Math.abs(to.x-b.x)<b.w/2+r&&Math.abs(to.z-b.z)<b.d/2+r);}
function interact(){if(!near)return;if(near.type==='garageService')garageServiceDialog();else if(near.type==='building')enter(near.b);else if(near.type==='elevator')elevatorDialog();else if(near.type==='home')housingDialog();else if(near.type==='neighbor')toast(housing.resident(interiorFloor)+'：我住'+interiorFloor+'02室，一起去公园散步吧！');else if(near.type==='service')service(interior);else if(near.type==='exit')leave();else if(near.type==='bed')sleepHotel();else if(near.type==='person'){if(near.p.building)enter(near.p.building);else toast(near.p.resident?'住户：我住在'+near.p.home+'，楼上的01室可以买房，02室是邻居家。':'路人：你好！新区有公园、小区、游乐园和购物中心。');}}
$('interact').onclick=interact;window.addEventListener('keydown',e=>{if($('dialog').open||$('phone-dialog').open)return;sound.unlock();if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys.add(e.code);if(!e.repeat&&e.code==='KeyE')interact();if(!e.repeat&&e.code==='KeyF')toggleCar();if(!e.repeat&&e.code==='KeyQ')toggleSignal('left');if(!e.repeat&&e.code==='KeyR')toggleSignal('right');if(!e.repeat&&e.code==='KeyP')phoneUI.open();});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();if(document.hidden)sound.stopEngine();});
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);b.classList.add('active');};for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>{keys.delete(b.dataset.key);b.classList.remove('active');});}
renderer.domElement.addEventListener('pointerdown',e=>{drag={id:e.pointerId,x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(drag&&drag.id===e.pointerId){orbit-=(e.clientX-drag.x)*.006;pitch=THREE.MathUtils.clamp(pitch+(drag.y-e.clientY)*.006,-.6,1.5);drag.x=e.clientX;drag.y=e.clientY;}});for(const event of ['pointerup','pointercancel','lostpointercapture'])renderer.domElement.addEventListener(event,()=>drag=null);
function signalAllowed(c){const phase=trafficPhase(time);return phase===c.axis;}
function updateTraffic(dt){for(const c of traffic){c.previous.copy(c.g.position);if(c.route){c.speed=world.roadAt(c.g.position).type==='highway'?28:12;advanceRoute(c,dt);continue;}const origin=c.origin??{x:0,z:0};const pos=c.axis==='NS'?c.g.position.z-origin.z:c.g.position.x-origin.x;let stop=false;for(const cross of [-44,0,44]){const ahead=(cross-pos)*c.dir;if(ahead>6&&ahead<13&&!signalAllowed(c))stop=true;}const moving=stop?0:c.speed*dt;if(c.axis==='NS')c.g.position.z+=moving*c.dir;else c.g.position.x+=moving*c.dir;const next=c.axis==='NS'?c.g.position.z-origin.z:c.g.position.x-origin.x;if(Math.abs(next)>93){if(c.axis==='NS')c.g.position.z=origin.z-next;else c.g.position.x=origin.x-next;c.previous.copy(c.g.position);}c.moving=!stop;}}
function collision(dt){if(world.mode==='highway'||flight||taxi?.phase==='riding'||justice.phase!=='free'||interior||time-lastCollision<2)return;const p=driving?activeCar.g.position:player.g.position;for(const c of traffic){if(Math.abs(p.y-c.g.position.y)>2)continue;if(p.distanceTo(c.g.position)<(driving?3.2:1.65)){const phase=trafficPhase(time),red=driving&&[-44,0,44].some(x=>[-44,0,44].some(z=>Math.abs(p.x-world.region.x-x)<6&&Math.abs(p.z-world.region.z-z)<6))&&phase!==(Math.abs(Math.cos(heading))>.7?'NS':'EW');const result=collisionClaim({driving,speed,npcMoving:c.moving,playerRed:red});if(!result)continue;record(result.text,result.amount);if(result.fault)addCrime(40);lastCollision=time;if(driving){speed=0;const f=new THREE.Vector3(-Math.sin(heading)*2,0,-Math.cos(heading)*2);activeCar.g.position.add(f);}else{player.g.position.x+=3;player.g.position.z+=1;}c.g.position.copy(c.previous);return;}}if(driving&&Math.abs(speed)>1.5){for(const p of people){if(p.g.position.distanceTo(activeCar.g.position)<2){record('你开车撞到了路人，赔偿 ¥1,500。',-1500);addCrime(50);lastCollision=time;speed=0;activeCar.g.position.x+=2;return;}}}}
function addCrime(points){justice.add(points);updateCrimeUI();}
function updateCrimeUI(){const locked=justice.phase!=='free';$('crime-progress').value=justice.progress;$('crime-value').textContent=`${justice.progress.toLocaleString()} / ${CRIME_MAX.toLocaleString()}`;$('crime-note').textContent=justice.phase==='escort'?'警察正在押送你到法院':justice.phase==='court'?'法院审理中 · 罚款 ¥200,000':'满格后警察带往法院，罚款 ¥200,000';for(const id of ['car-toggle','exit','recover','map-toggle','ledger-toggle','phone-toggle','travel-toggle'])$(id).disabled=locked||!!flight;}
const arrestOfficer=person(city,0,0,0x31588b,'警察');arrestOfficer.g.visible=false;
function beginArrest(){if(!justice.begin())return;if(world.mode==='highway')world.cancelHighway();navigation=null;elevatorTrip=null;interiorFloor=1;viewingHome=false;custodyCourt=null;cancelTaxi(false);keys.clear();$('dialog').close();activity=null;speed=0;driving=false;activeCar=null;player.g.visible=true;arrestOfficer.g.position.copy(player.g.position);arrestOfficer.g.position.x+=1.5;arrestOfficer.g.visible=true;toast('犯罪进度已满！警察把你带往城市法院。');updateCrimeUI();}
function updateJustice(dt){if(justice.phase==='wanted')beginArrest();if(justice.phase==='escort'){arrestOfficer.g.position.copy(player.g.position);arrestOfficer.g.position.x+=1.5;animatePerson(arrestOfficer,true,dt);}const event=justice.advance(dt);if(event==='court'){const court=custodyCourt??buildings.filter(b=>b.id==='court').sort((a,b)=>Math.hypot(a.x-player.g.position.x,a.z-player.g.position.z)-Math.hypot(b.x-player.g.position.x,b.z-player.g.position.z))[0];custodyCourt=court;player.g.removeFromParent();buildInterior(court);interior=court;city.visible=false;inside.visible=true;inside.add(player.g);player.g.position.set(260,0,2);heading=Math.PI;orbit=0;pitch=0;arrestOfficer.g.visible=false;scene.fog=new THREE.Fog(0xd5ddc5,60,160);$('location').textContent='城市法院';$('exit').hidden=true;toast('警察已把你带到法院。法官正在审理，罚款 ¥200,000。');}else if(event==='release'){const court=custodyCourt??buildings.filter(b=>b.id==='court').sort((a,b)=>Math.hypot(a.x-player.g.position.x,a.z-player.g.position.z)-Math.hypot(b.x-player.g.position.x,b.z-player.g.position.z))[0];custodyCourt=court;record('法院罚款 · 犯罪进度满格',-200000);interior=null;inside.visible=false;city.visible=true;city.add(player.g);player.g.position.set(court.door.x,surfaceHeight(court.door.x,court.door.z+2),court.door.z+2);heading=0;player.g.rotation.y=heading;scene.fog=new THREE.Fog(0xc6e0e8,140,330);$('exit').hidden=true;lastCollision=time;toast('已缴纳罚款 ¥200,000，在法院门口释放。犯罪进度已清零。');}updateCrimeUI();}
function updateCountdown(light){const info=trafficCountdown(time,light.axis);const text=`${info.green?'绿':'红'} ${info.seconds}`;if(text===light.lastText)return;light.lastText=text;const texture=light.countdown.material.map,canvas=texture.image,c=canvas.getContext('2d');c.fillStyle='#203634';c.fillRect(0,0,canvas.width,canvas.height);c.fillStyle=info.green?'#6de6a5':'#ff9a7f';c.font=`bold ${Math.floor(canvas.height*.42)}px sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillText(text,canvas.width/2,canvas.height/2,canvas.width-20);texture.needsUpdate=true;}
let finedAt=-20;function redLightFine(previous,p){if(world.mode!=='city'||!driving||time-finedAt<5)return;for(const x of [-44,0,44].map(v=>v+world.region.x))for(const z of [-44,0,44].map(v=>v+world.region.z)){const entered=Math.abs(p.x-x)<5&&Math.abs(p.z-z)<5&&!(Math.abs(previous.x-x)<5&&Math.abs(previous.z-z)<5);if(entered&&trafficPhase(time)!==(Math.abs(Math.cos(heading))>.7?'NS':'EW')){finedAt=time;record('警察：闯红灯，罚款 ¥200。',-200);addCrime(20);}}}
function updatePlayer(dt){if(flight){updateCabinPlayer(dt);return;}if(navigation){updateNavigation(dt);return;}if(taxi?.phase==='riding'||justice.phase!=='free'||activity||elevatorTrip||$('dialog').open||$('phone-dialog').open)return;const f=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),turn=(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)-(keys.has('KeyD')||keys.has('ArrowRight')?1:0);const obj=driving?activeCar.g:player.g;const before=obj.position.clone();if(driving){speed+=f*12*dt;speed*=Math.exp(-(f? .15:1.7)*dt);if(keys.has('Space'))speed*=Math.exp(-9*dt);speed=THREE.MathUtils.clamp(speed,-12,world.roadAt(obj.position).type==='highway'?33.33:world.roadAt(obj.position).type==='ramp'?11.1:16.67);heading+=turn*dt*1.5*(Math.abs(speed)> .3?Math.sign(speed):0);}else{heading+=turn*dt*2.5;speed=f*5;}const to={x:obj.position.x-Math.sin(heading)*speed*dt,z:obj.position.z-Math.cos(heading)*speed*dt};if(validMove(obj.position,to,driving?1.4:.4)){obj.position.x=to.x;obj.position.z=to.z;}else{if(driving&&Math.abs(speed)>4&&time-lastCollision>2&&!garageAccess.blocks(obj.position,to,1.4,activeCar.plate)){record('车辆碰撞建筑，赔偿修理费 ¥800。',-800);addCrime(10);lastCollision=time;}speed=0;}obj.position.y=interior?(interiorFloor-1)*4:surfaceHeight(obj.position.x,obj.position.z);obj.rotation.y=heading;if(driving)player.g.position.copy(obj.position);animatePerson(player,!driving&&Math.abs(speed)>.1,dt);redLightFine(before,obj.position);if(driving)updateCityTravel();}
