// The phone shows the same number the driver verifies after boarding.
const PHONE_SUFFIX='123456';
function roadPoint(p){const q=world.nearestStreet(p);return {x:q.x,z:q.z,axis:q.axis};}
function taxiRoute(from,to){return world.streetRoute(from,to);}
function taxiPhone(){if(justice.phase!=='free')return;dialog('我的手机 · 打车',`本机手机尾号：${PHONE_SUFFIX}。上车后告诉司机这个号码。`);if(taxi){row('车牌 '+taxi.car.plate,`目的地：${taxi.destination.name} · ${taxi.phase==='arriving'?'司机正在来接你':taxi.phase==='waiting'?'司机已到，请走近上车':taxi.phase==='riding'?'行程中':'等待尾号确认'}`);if(taxi.phase==='waiting')row('上车验证尾号','走近出租车后即可上车',()=>{if(taxi.car.g.position.distanceTo(player.g.position)>=7){toast('请先走近车牌 '+taxi.car.plate+' 的出租车。');return;}verifyTaxi();},'上车');if(taxi.phase!=='riding')row('取消这次打车','取消后可以重新选择目的地',()=>{cancelTaxi();$('dialog').close();},'取消');return;}if(interior||driving||player.g.position.y<-.5||activity){row('请到地面街道叫车','先出门、下车或离开地下停车场。');return;}for(const b of buildings.filter(b=>Math.abs(b.x-world.region.x)<190&&Math.abs(b.z-world.region.z)<190))row(b.name,'司机送你到建筑门前附近',()=>requestTaxi(b),'打车');row('地下停车场入口','送到地面坡道入口',()=>requestTaxi({id:'garage',name:'地下停车场入口',door:{x:20,z:45}}),'打车');}
$('phone-toggle').onclick=()=>phoneUI.open();
function requestTaxi(destination){if(world.mode!=='city'||taxi||interior||driving||flight||justice.phase!=='free')return;if(!wallet.canPay(35)){toast('打车需要35元，请先去写字楼上班。');return;}if(Math.abs(player.g.position.x-world.region.x)>190||Math.abs(player.g.position.z-world.region.z)>190){toast('高速无法接客，请先回到附近城市街道再叫车。');return;}const pickup=roadPoint(player.g.position),dropoff=roadPoint(destination.door);const start=roadPoint({x:pickup.x+25,z:pickup.z+25});const vehicle=car(city,start.x,start.z,0xe9bc53,0,false,'城A·T1234');box(vehicle.g,0,1.82,0,1.1,.3,.5,0xf8e8a3);sign(vehicle.g,'出租车',0,2.05,0,2.7,'#315a48','#fff6d4');const driver=person(vehicle.g,.55,-.3,0x537d80,'司机');driver.g.scale.setScalar(.48);driver.g.position.y=.68;taxi={car:vehicle,destination,pickup,dropoff,phase:'arriving',route:world.streetRoute(start,pickup),index:0};$('dialog').close();toast(`打车成功！车牌 ${vehicle.plate}，手机尾号 ${PHONE_SUFFIX}。司机正前来接你。`);}
function verifyTaxi(){if(!taxi||taxi.phase!=='waiting')return;taxi.phase='verify';taxi.boardingPosition=player.g.position.clone();player.g.visible=false;player.g.position.copy(taxi.car.g.position);dialog('司机：请问手机尾号是多少？',`你已上车。车牌 ${taxi.car.plate} · 目的地 ${taxi.destination.name}。手机上写着尾号 ${PHONE_SUFFIX}。`);const input=document.createElement('input');input.type='text';input.inputMode='numeric';input.autocomplete='off';input.maxLength=6;input.placeholder='输入手机尾号';input.setAttribute('aria-label','手机尾号');input.style.cssText='width:100%;padding:14px;border:1px solid #b7c8b3;border-radius:12px;font:inherit';$('dialog-content').append(input);row('确认手机尾号','填写 123456，核对后出发',()=>confirmTaxi(input.value),'确认');input.focus();}
function confirmTaxi(answer){if(!taxi||taxi.phase!=='verify')return false;if(String(answer).trim()!==PHONE_SUFFIX){toast('司机：尾号不对，请看一下手机上的号码。');return false;}taxi.phase='riding';taxi.route=taxiRoute(taxi.pickup,taxi.dropoff);taxi.index=0;keys.clear();speed=0;player.g.visible=false;player.g.position.copy(taxi.car.g.position);heading=taxi.car.g.rotation.y;$('dialog').close();toast('司机：尾号对了，请坐好，现在出发！');return true;}
$('dialog').addEventListener('close',()=>{if(taxi?.phase==='verify'){taxi.phase='waiting';player.g.visible=true;if(taxi.boardingPosition)player.g.position.copy(taxi.boardingPosition);}});
function cancelTaxi(notify=true){if(!taxi)return;if(taxi.phase==='verify'&&taxi.boardingPosition)player.g.position.copy(taxi.boardingPosition);city.remove(taxi.car.g);player.g.visible=true;taxi=null;if(notify)toast('已取消打车。');}
function updateTaxi(dt){if(!taxi||!['arriving','riding'].includes(taxi.phase))return;const c=taxi.car.g,target=taxi.route[taxi.index];if(!target)return;const dx=target.x-c.position.x,dz=target.z-c.position.z,distance=Math.hypot(dx,dz),axis=Math.abs(dz)>Math.abs(dx)?'NS':'EW';let stop=false;for(const x of [-44,0,44].map(v=>v+world.region.x))for(const z of [-44,0,44].map(v=>v+world.region.z)){const along=axis==='NS'?(z-c.position.z)*Math.sign(dz):(x-c.position.x)*Math.sign(dx),across=axis==='NS'?Math.abs(c.position.x-x):Math.abs(c.position.z-z);if(across<5&&along>6&&along<10&&trafficPhase(time)!==axis)stop=true;}if(!stop&&distance>.15){const step=Math.min(distance,12*dt);c.position.x+=dx/distance*step;c.position.z+=dz/distance*step;c.rotation.y=Math.atan2(-dx,-dz);c.position.y=surfaceHeight(c.position.x,c.position.z);}if(taxi.phase==='riding'){player.g.position.copy(c.position);heading=c.rotation.y;}if(distance<=.5){taxi.index++;if(taxi.index<taxi.route.length)return;if(taxi.phase==='arriving'){taxi.phase='waiting';toast(`司机到了！找车牌 ${taxi.car.plate}，走近后按 F 上车。`);}else{const dest=taxi.destination;record('打车到 '+dest.name,-35);player.g.visible=true;player.g.position.set(dest.door.x,surfaceHeight(dest.door.x,dest.door.z+2),dest.door.z+2);speed=0;heading=0;player.g.rotation.y=0;cancelTaxi(false);lastCollision=time;toast('已到达'+dest.name+'，车费 ¥35 已支付。');}}}

