function updateDayNight(){if(flight){scene.background=new THREE.Color(0x7bc6f4);scene.fog.color.copy(scene.background);sun.intensity=2.4;ambient.intensity=2.5;ambient.groundColor.setHex(0xb8d4e3);moon.visible=false;stars.visible=false;const pos=flight.visual.aircraft.position;sun.position.set(pos.x+60,pos.y+140,pos.z+40);sun.target.position.copy(pos);sun.target.updateMatrixWorld();return;}ambient.groundColor.setHex(0x82967a);const night=interior?.id==='hotel'&&activity?.kind==='stay'?0:nightStrength(dayMinutes);const p=player.g.position;moon.visible=!interior&&night>0;stars.visible=!interior&&night>.3;moon.position.set(p.x+60,p.y+30+night*40,p.z-90);stars.position.set(p.x,0,p.z);const sky=new THREE.Color(countries[world.country].sky).lerp(new THREE.Color(0x122039),night);scene.background=sky;if(!interior){scene.fog.color.copy(sky);sun.intensity=2.8*(1-night)+.2;ambient.intensity=2.2*(1-night)+.8;}else{sun.intensity=1;ambient.intensity=2;}sun.position.set(p.x+30,70,p.z+30);sun.target.position.set(p.x,0,p.z);sun.target.updateMatrixWorld();}
function setLamp(lamp,on,color){lamp.material.color.setHex(on?color:0x493a31);lamp.material.emissive.setHex(on?color:0x000000);lamp.material.emissiveIntensity=on?1.4:0;}
function toggleSignal(direction){if(!driving){toast('先上车，再打开转向灯。');return;}signal=signal===direction?null:direction;lastIndicator=-1;}
function updateCarEffects(){const braking=driving&&(keys.has('Space')||keys.has('KeyS')||keys.has('ArrowDown'));if(braking&&!wasBraking)sound.play('brake');wasBraking=braking;const direction=driving?(signal??((keys.has('KeyA')||keys.has('ArrowLeft'))?'left':(keys.has('KeyD')||keys.has('ArrowRight'))?'right':null)):null;const tick=Math.floor(time/.55),blink=tick%2===0;if(direction&&tick!==lastIndicator){lastIndicator=tick;sound.play('indicator');}for(const c of [...parked,...traffic,...(taxi?[taxi.car]:[])]){const own=driving&&c===activeCar;for(const lamp of c.brakeLights)setLamp(lamp,own?braking:c.npc&&!c.moving,0xff3930);for(const side of ['left','right'])for(const lamp of c.indicators[side])setLamp(lamp,own&&direction===side&&blink,0xffb737);}$('signal-left').classList.toggle('active',direction==='left');$('signal-right').classList.toggle('active',direction==='right');}
$('signal-left').onclick=()=>toggleSignal('left');$('signal-right').onclick=()=>toggleSignal('right');function toggleSound(){const enabled=sound.toggle();for(const id of ['sound-toggle','flight-sound'])$(id).textContent=enabled?'音效：开':'音效：关';}$('sound-toggle').onclick=toggleSound;$('flight-sound').onclick=toggleSound;document.addEventListener('pointerdown',()=>sound.unlock(),{capture:true});
function eatInventory(index){if(activity||flight||driving||justice.phase!=='free')return;const name=inventory[index];if(!name)return;inventory.splice(index,1);$('dialog').close();sound.play('eat');lastEat=Math.floor(time*3);activity={end:time+3,b:{id:'snack'},name,kind:'food'};toast('正在吃 / 喝 '+name+'……');}
function sleepHotel(){if(!interior||interior.id!=='hotel'||!hotelKey||activity)return;player.g.position.set(267,(interiorFloor-1)*4,-3);activity={end:time+5,b:interior,name:'客房休息',kind:'stay'};toast('在独立客房休息，醒来就是第二天早晨。');}
function travelDialog(){
 dialog('世界导航 · 694座中国城市',world.region.country+' · '+world.region.name+'。每座城市拥有独立街道、建筑和地形。先选择目的地，再自己驾驶上高速，或开启辅助驾驶。');const routes=highwayNames(world.country);row(routes.join(' / '),'入口：东176米南132米，收费60元。驶上高速到达城市出口时切换地图。');row('当前高速目的地：'+world.destination.name,'开车驶过城市边缘的高速出口，即可开始跨城行程。');
 row('去国际机场','16个国家，发动机音效、起降和航站楼动画。',()=>{const airport=buildings.find(b=>b.id==='airport'&&b.chunk===world.region.key);if(interior||driving){toast('先出门、下车，再去机场。');return;}requestTaxi(airport);},'打车去机场');
 row('新区生活','地图中可以找公园、九座小区、游乐园和购物中心。');
 if(navigation)row('正在去 '+navigation.destination.name,'可以停止辅助驾驶，接着自己开。',()=>{navigation=null;speed=0;$('dialog').close();},'停止辅助驾驶');
 if(world.country!==0){row('中国城市导航','乘机回到中国后，可搜索全部694座城市。');return;}
 const input=document.createElement('input');input.placeholder='搜索城市 / 省份（694座）';input.setAttribute('aria-label','搜索城市');input.className='city-search';$('dialog-content').append(input);const list=document.createElement('div');$('dialog-content').append(list);
 function results(){list.replaceChildren();const matches=findCities(input.value??'');const count=document.createElement('p');count.textContent='找到 '+matches.length+' 座城市';list.append(count);for(const dest of matches.slice(0,40)){const item=document.createElement('div');item.className='item';const name=document.createElement('span');name.textContent=dest.name+' · '+dest.province;const go=document.createElement('button');go.textContent='自己驾驶';go.onclick=()=>{if(!world.selectDestination(dest)){toast('当前城市已到达，或正在高速途中。');return;}$('dialog').close();toast('高速目的地已设为'+dest.name+'。请驾车经匝道上高速，再驶过城市边缘的出口。');};const assist=document.createElement('button');assist.textContent='辅助驾驶';assist.onclick=()=>startNavigation(dest);item.append(name,go,assist);list.append(item);}}input.oninput=results;results();
}
$('travel-toggle').onclick=travelDialog;
function setDrivingPose(pose){
 activeCar.g.position.set(pose.x,pose.y,pose.z);activeCar.g.rotation.set(0,pose.heading,0);heading=pose.heading;player.g.position.copy(activeCar.g.position);camera.position.set(pose.x+Math.sin(heading)*14,pose.y+8,pose.z+Math.cos(heading)*14);orbit=0;pitch=0;lastCollision=time;
 document.body?.classList.add('city-changing');setTimeout(()=>document.body?.classList.remove('city-changing'),650);
}
function updateCityTravel(){
 if(!driving||interior||flight)return;const p=activeCar.g.position;
 if(world.departureAt(p,true)){
  const pose=world.beginHighway();if(!pose)return;setDrivingPose(pose);
  if(navigation)navigation={...navigation,phase:'highway',route:world.trip.points,index:1,remaining:world.trip.length};
  toast('驶入跨城高速：'+world.profile.name+' → '+world.trip.destination.name+'。到达出口后加载目的地地图。');return;
 }
 const arrived=world.arrivalAt(p,true);if(arrived){setDrivingPose(arrived.pose);if(navigation&&arrived.route)navigation={...navigation,phase:'city-arrival',route:arrived.route,index:1,remaining:220};else navigation=null;toast('已切换到'+world.profile.name+'的独立地图，沿匝道下高速进入城区。');}
}
function startNavigation(destination){
 if(flight||interior||activity||taxi||justice.phase!=='free'||player.g.position.y<-.5){toast('请先回到地面街道，结束当前活动。');return false;}
 if(world.mode==='highway'){
  if(!driving||destination.name!==world.trip.destination.name){toast('高速途中请先到达当前目的地出口。');return false;}
  navigation={destination,phase:'highway',route:[{...activeCar.g.position},world.trip.points.at(-1)],index:1,remaining:world.trip.length-activeCar.g.position.z};$('dialog').close();return true;
 }
 if(!world.selectDestination(destination)){toast('已经在'+world.profile.name+'，请选择另一座城市。');return false;}
 if(!driving){activeCar=parked.find(c=>c.plate===playerPlate)??parked.find(c=>!c.npc&&c.g.position.y>=0);if(!activeCar)return false;const direction=activeCar.g.getWorldDirection(new THREE.Vector3());heading=Math.atan2(direction.x,direction.z);city.attach(activeCar.g);activeCar.g.rotation.set(0,heading,0);driving=true;playerPlate=activeCar.plate;player.g.visible=false;player.g.position.copy(activeCar.g.position);}
 const route=world.departureRoute(activeCar.g.position);if(route.length<2){toast('请把车开到城市街道再导航。');return false;}
 navigation={destination,phase:'city-departure',route,index:1,remaining:0};keys.clear();speed=0;$('dialog').close();toast('沿当前城市街道和匝道上高速。到目的地出口后切换地图，WASD可接管驾驶。');return true;
}
function updateNavigation(dt){
 if([...keys].some(k=>['KeyW','KeyS','KeyA','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(k))){navigation=null;speed=0;return;}
 const n=navigation,p=activeCar.g.position,target=n.route[n.index];if(!target){if(n.phase==='city-departure'||n.phase==='highway'){updateCityTravel();return;}navigation=null;speed=0;lastCollision=time;toast('已经下高速，到达'+n.destination.name+'！按F下车。');return;}
 const limit=world.roadAt(p).limit/3.6,dx=target.x-p.x,dz=target.z-p.z,d=Math.hypot(dx,dz),step=Math.min(d,limit*dt);world.updateTolls(p,true,time);
 if(d>.001){p.x+=dx/d*step;p.z+=dz/d*step;p.y=surfaceHeight(p.x,p.z);heading=Math.atan2(-dx,-dz);activeCar.g.rotation.set(0,heading,0);}
 speed=limit;player.g.position.copy(p);lastCollision=time;if(d<=step+.001)n.index++;n.remaining=Math.max(0,d-step);for(let i=n.index+1;i<n.route.length;i++)n.remaining+=Math.hypot(n.route[i].x-n.route[i-1].x,n.route[i].z-n.route[i-1].z);updateCityTravel();
}
function flightMenu(){if(interior?.id!=='airport'){toast('请到机场柜台购买机票。');return;}dialog('国际航班',`现在位于${countries[world.country].name}，请选择目的地。`);countries.forEach((country,index)=>{if(index!==world.country)row(country.name+' · '+country.cities[0],'机票 ¥3,800 · 离港、起飞、机舱漫步与云海',()=>bookFlight(index),'购买并登机');});}
function bookFlight(country){
 if(interior?.id!=='airport'||flight||justice.phase!=='free'||!Number.isInteger(country)||!countries[country]||country===world.country)return false;
 if(!wallet.canPay(3800)){toast('机票需要3800元，请先去写字楼上班赚钱。');return false;}record('国际机票 · 飞往'+countries[country].name,-3800);$('dialog').close();keys.clear();cancelTaxi(false);activity=null;
 flight={country,elapsed:0,stage:flightStageAt(0),view:'exterior',velocity:0,altitude:0,landing:null};
 buildFlightCabin();player.g.position.set(0,0,8);heading=0;orbit=0;pitch=0;speed=0;
 scene.fog=new THREE.Fog(0x7bc6f4,150,650);camera.far=900;camera.updateProjectionMatrix();camera.position.set(-7,20,104);
 document.body?.classList.toggle('in-flight',true);$('exit').hidden=true;$('minimap').hidden=true;$('flight-panel').hidden=false;updateFlight(0);sound.play('flight');toast('已登机！廊桥即将收回，飞机准备离开航站楼。');return true;
}
function setFlightView(view){if(!flight)return;flight.view=view;inside.visible=view==='cabin';flight.visual.exterior.visible=view==='exterior';orbit=0;pitch=0;if(view==='exterior'){const p=flight.visual.aircraft.position;camera.position.set(p.x-34,p.y+20,p.z+34);}$('flight-view').textContent=view==='cabin'?'查看飞机外景':'进入机舱';keys.clear();}
function startLanding(){if(!flight||flight.stage.id!=='cruise'||flight.landing!==null)return false;flight.landing=0;setFlightView('exterior');sound.play('flight');return true;}
function finishFlight(){
 const destination=flight.country;player.g.removeFromParent();flight.visual.dispose();sound.stopEngine();flight=null;
 city.add(player.g);player.g.visible=true;interior=null;inside.visible=false;city.visible=true;world.fly(destination);
 const airport=buildings.find(b=>b.id==='airport');player.g.position.set(airport.door.x,surfaceHeight(airport.door.x,airport.door.z+2),airport.door.z+2);heading=0;player.g.rotation.y=0;speed=0;driving=false;activeCar=null;orbit=0;pitch=0;keys.clear();
 scene.fog=new THREE.Fog(countries[destination].sky,140,330);camera.far=450;camera.updateProjectionMatrix();camera.position.set(player.g.position.x,player.g.position.y+8,player.g.position.z+10);
 document.body?.classList.toggle('in-flight',false);$('exit').hidden=true;$('flight-panel').hidden=true;$('minimap').hidden=false;lastCollision=time;updateCrimeUI();toast('欢迎来到'+countries[destination].name+'！已抵达国际机场门口，可以继续打车或探索。');
}
function updateFlight(dt){
 if(!flight)return;flight.elapsed+=dt;
 const previous=flight.stage.id;
 if(flight.landing!==null){flight.landing+=dt;const arrival=arrivalStageAt(flight.landing);if(!arrival){finishFlight();return;}flight.stage=arrival;}
 else flight.stage=flightStageAt(flight.elapsed);
 if(previous!==flight.stage.id){keys.clear();sound.play('flight');toast(flight.stage.hint);if(flight.stage.id==='cruise')setFlightView('cabin');}
 const state=flight.visual.update(flight.elapsed,flight.stage,dt);flight.velocity=state.velocity;flight.altitude=state.altitude;sound.engine(flight.stage.id,flight.velocity);if(flight.stage.id==='landing'&&flight.stage.progress>=.72&&!flight.touchdown){flight.touchdown=true;sound.play('touchdown');toast('主轮接地，轮胎摩擦跑道，正在减速。');}
 $('flight-route').textContent=countries[world.country].name+' → '+countries[flight.country].name;$('flight-stage').textContent=flight.stage.label;
 $('flight-altitude').textContent=flight.altitude.toLocaleString()+' m';$('flight-speed').textContent=flight.velocity+' km/h';
 $('flight-progress').value=flight.landing!==null?85+Math.min(15,flight.landing/22*15):Math.min(85,flight.elapsed/26*85);
 $('flight-arrive').disabled=flight.stage.id!=='cruise';$('flight-arrive').textContent=flight.landing!==null?'正在到达航站楼……':'结束巡航 · 降落目的地';
 $('flight-hint').textContent=flight.stage.hint;
}
function updateCabinPlayer(dt){
 if(!flight||flight.view!=='cabin')return;
 if(flight.stage.id!=='cruise'){animatePerson(player,false,dt);return;}
 const f=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0);
 const turn=(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)-(keys.has('KeyD')||keys.has('ArrowRight')?1:0);heading+=turn*dt*2.1;
 const p=player.g.position,to={x:p.x-Math.sin(heading)*f*3.5*dt,z:p.z-Math.cos(heading)*f*3.5*dt};
 if(cabinCanMove(to)){p.x=to.x;p.z=to.z;}else{const alongX={x:to.x,z:p.z},alongZ={x:p.x,z:to.z};if(cabinCanMove(alongX))p.x=to.x;if(cabinCanMove(alongZ))p.z=to.z;}
 p.y=0;player.g.rotation.y=heading;animatePerson(player,!!f,dt);
}
function buildFlightCabin(){
 player.g.removeFromParent();while(inside.children.length){const g=inside.children[0];inside.remove(g);g.traverse(o=>{o.geometry?.dispose();if(o.material?.map){o.material.map.dispose();o.material.dispose();}});}
 flight.visual=createFlightScene({THREE,scene,inside,box,sphere,sign,destination:countries[flight.country].name});inside.add(player.g);player.g.visible=false;city.visible=false;inside.visible=false;
 $('flight-view').textContent='进入机舱';
}
$('flight-view').onclick=()=>setFlightView(flight?.view==='cabin'?'exterior':'cabin');$('flight-arrive').onclick=startLanding;

const meal=sphere(player.g,.45,1.5,-.3,.17,0xd4a35d);meal.visible=false;
function updateEating(){meal.visible=activity?.kind==='food';if(meal.visible){const bite=(Math.sin(time*6)+1)/2;player.arms[1].rotation.x=-1-bite*.6;meal.position.y=1.2+bite*.5;meal.position.z=-.25-bite*.2;}}

function surfaceHeight(x,z){return world.surfaceHeight(x,z);}
function updateWallet(){$('money-value').textContent='钱包 ¥'+moneyText(wallet.balance);$('health-value').textContent='健康 '+health+'/100';}
function spend(text,amount){if(!wallet.canPay(amount)){toast('余额不足，请去写字楼上班赚钱。');return false;}record(text,-amount);return true;}
function stopWork(){if(activity?.kind!=='work')return;const due=wagesDue(activity.start,time,activity.paid);if(due)record('写字楼工资',due*WAGE);activity=null;$('work-stop').hidden=true;toast('已下班，工资已存入钱包。');}
$('work-stop').onclick=stopWork;
function bankDialog(){dialog('城市银行 · 账户',`钱包 ¥${moneyText(wallet.balance)} · 存款 ¥${wallet.deposits.toLocaleString()}`);for(const amount of [50,100,500]){row('存入 ¥'+amount,'转入银行账户',()=>{if(!wallet.deposit(amount)){toast('钱包余额不足。');return;}ledger.unshift({text:'银行存款',amount:-amount});updateWallet();bankDialog();},'存款');row('取出 ¥'+amount,'取回钱包使用',()=>{if(!wallet.withdraw(amount)){toast('银行存款不足。');return;}ledger.unshift({text:'银行取款',amount});updateWallet();bankDialog();},'取款');}}
const phoneUI=createCityPhone({getState:()=>({balance:wallet.balance,deposits:wallet.deposits,health,ledger,inventory,time,region:world.region.country+' · '+world.region.name,locked:justice.phase!=='free'||!!flight}),spend,record,toast,taxi:taxiPhone,bank:bankDialog,tracks:window.ConcertTracks??[]});
